// Generated by Claude Code
package grading.reporting;

import grading.reporting.PdfText.Run;
import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.logging.Level;
import java.util.logging.Logger;
import org.apache.pdfbox.pdmodel.PDDocument;

/**
 * Lays out a report written in the small Markdown subset produced by the report formatters as an
 * A4 PDF: headings, paragraphs, bullet lists, tables, code blocks, and bold, italic and code text.
 * This class reads the Markdown block by block; {@link PdfText} handles inline text,
 * {@link PdfTable} tables and {@link PdfPages} the pages they are drawn on.
 */
final class PdfReportRenderer {

    private static final float BODY_SIZE = 9.5f;
    private static final float CODE_SIZE = 7.5f;
    private static final float CODE_PADDING = 3;
    private static final float BULLET_INDENT = 12;
    private static final float KEEP_WITH_HEADING = 60;
    // Font sizes and the space above each heading level (#, ## and ###).
    private static final float TITLE_SIZE = 16;
    private static final float TITLE_SPACE = 4;
    private static final float SECTION_SIZE = 13;
    private static final float SECTION_SPACE = 10;
    private static final float SUBSECTION_SIZE = 11;
    private static final float SUBSECTION_SPACE = 6;
    // Vertical gaps, as fractions of the text size: a blank line or code block, below a heading, below a table.
    private static final float HALF_LINE = 0.5f;
    private static final float HEADING_GAP = 0.3f;
    private static final float TABLE_GAP = 0.6f;
    // The bullet sits this far into the indent before the bullet's text.
    private static final float BULLET_OFFSET = 0.75f;
    private static final String CODE_FENCE = "```";
    private static final String TABLE_ROW = "|";
    private static final String BULLET = "- ";
    private static final String NESTED_BULLET = "  - ";
    // PDFBox indexes the system fonts the first time it creates a font and logs a warning for every
    // font it cannot read; those warnings say nothing about the report, so only errors are shown.
    private static final Logger PDFBOX_LOG = Logger.getLogger("org.apache.pdfbox");

    static {
        PDFBOX_LOG.setLevel(Level.SEVERE);
    }

    private final PdfText text = new PdfText();
    private PdfPages pages;

    /** Writes the report to {@code pdf}; the footer of every page shows {@code footer} and the page number. */
    void render(String markdown, Path pdf, String footer) throws IOException {
        try (PDDocument output = new PDDocument()) {
            pages = new PdfPages(output, text);
            layOut(markdown.replace("\r", "").split("\n", -1));
            pages.finish(footer);
            output.getDocumentInformation().setTitle(footer);
            output.save(pdf.toFile());
        } finally {
            pages = null;
        }
    }

    private void layOut(String[] lines) throws IOException {
        int index = 0;
        StringBuilder paragraph = new StringBuilder();
        while (index < lines.length) {
            String line = lines[index];
            if (endsParagraph(line)) {
                flushParagraph(paragraph);
            }
            if (line.startsWith(CODE_FENCE)) {
                List<String> code = new ArrayList<>();
                index++;
                while (index < lines.length && !lines[index].startsWith(CODE_FENCE)) {
                    code.add(lines[index++]);
                }
                codeBlock(code);
            } else if (line.startsWith(TABLE_ROW)) {
                List<String> rows = new ArrayList<>();
                while (index < lines.length && lines[index].startsWith(TABLE_ROW)) {
                    rows.add(lines[index++]);
                }
                table(rows);
                continue;
            } else if (line.startsWith("### ")) {
                heading(line.substring(4), SUBSECTION_SIZE, SUBSECTION_SPACE);
            } else if (line.startsWith("## ")) {
                heading(line.substring(3), SECTION_SIZE, SECTION_SPACE);
            } else if (line.startsWith("# ")) {
                heading(line.substring(2), TITLE_SIZE, TITLE_SPACE);
            } else if (line.startsWith(NESTED_BULLET)) {
                bullet(line.substring(NESTED_BULLET.length()), 2 * BULLET_INDENT);
            } else if (line.startsWith(BULLET)) {
                bullet(line.substring(BULLET.length()), BULLET_INDENT);
            } else if (line.isBlank()) {
                pages.moveDown(BODY_SIZE * HALF_LINE);
            } else {
                paragraph.append(paragraph.isEmpty() ? "" : " ").append(line.strip());
            }
            index++;
        }
        flushParagraph(paragraph);
    }

    // Every block other than plain text ends the paragraph before it.
    private static boolean endsParagraph(String line) {
        return line.startsWith(TABLE_ROW) || line.startsWith(CODE_FENCE) || line.startsWith("#") || line.isBlank()
                || line.startsWith(BULLET) || line.startsWith(NESTED_BULLET);
    }

    private void flushParagraph(StringBuilder paragraph) throws IOException {
        if (!paragraph.isEmpty()) {
            for (List<Run> line : text.wrap(text.runs(paragraph.toString(), text.regular), PdfPages.WIDTH,
                    BODY_SIZE)) {
                pages.drawLine(line, PdfPages.MARGIN, BODY_SIZE);
            }
            paragraph.setLength(0);
        }
    }

    private void heading(String heading, float size, float spaceBefore) throws IOException {
        pages.moveDown(spaceBefore);
        List<List<Run>> lines = text.wrap(text.runs(heading, text.bold), PdfPages.WIDTH, size);
        // keep a heading with the start of its section, such as a table's header and first row
        pages.ensureSpace(lines.size() * size * PdfText.LEADING + KEEP_WITH_HEADING);
        for (List<Run> line : lines) {
            pages.drawLine(line, PdfPages.MARGIN, size);
        }
        pages.moveDown(size * HEADING_GAP);
    }

    private void bullet(String item, float indent) throws IOException {
        List<List<Run>> lines = text.wrap(text.runs(item, text.regular), PdfPages.WIDTH - indent, BODY_SIZE);
        pages.ensureSpace(BODY_SIZE * PdfText.LEADING);
        pages.drawText(List.of(new Run("•", text.regular)),
                PdfPages.MARGIN + indent - BULLET_INDENT * BULLET_OFFSET, pages.y() - BODY_SIZE, BODY_SIZE);
        for (List<Run> line : lines) {
            pages.drawLine(line, PdfPages.MARGIN + indent, BODY_SIZE);
        }
    }

    private void codeBlock(List<String> code) throws IOException {
        float charWidth = PdfText.width("M", text.mono, CODE_SIZE);
        int perLine = Math.max(1, (int) ((PdfPages.WIDTH - 2 * CODE_PADDING) / charWidth));
        float lineHeight = CODE_SIZE * PdfText.LEADING;
        for (String line : wrapCode(code, perLine)) {
            pages.ensureSpace(lineHeight + CODE_PADDING);
            pages.fill(PdfPages.MARGIN, pages.y() - lineHeight, PdfPages.WIDTH, lineHeight, PdfPages.GREY_FILL);
            pages.drawText(List.of(new Run(line, text.mono)), PdfPages.MARGIN + CODE_PADDING,
                    pages.y() - CODE_SIZE, CODE_SIZE);
            pages.moveDown(lineHeight);
        }
        pages.moveDown(BODY_SIZE * HALF_LINE);
    }

    // Code keeps its spacing, so long lines are cut at a fixed number of characters instead of at words.
    private List<String> wrapCode(List<String> code, int perLine) {
        List<String> wrapped = new ArrayList<>();
        for (String line : code) {
            String remaining = text.printable(line.replace("\t", "    "), text.mono);
            do {
                wrapped.add(remaining.substring(0, Math.min(perLine, remaining.length())));
                remaining = remaining.length() > perLine ? remaining.substring(perLine) : "";
            } while (!remaining.isEmpty());
        }
        return wrapped;
    }

    private void table(List<String> rows) throws IOException {
        Optional<PdfTable> table = PdfTable.parse(rows, text);
        if (table.isPresent()) {
            table.get().draw(pages);
            pages.moveDown(BODY_SIZE * TABLE_GAP);
        }
    }
}
